import { spawn, ChildProcess } from 'child_process';
import path from 'path';

// Mapa do przechowywania aktywnych procesów w pamięci RAM backendu
const activeProcesses = new Map<string, ChildProcess>();

export const startServerLocal = (serverId: string, ram: number, jarPath: string) => {
  const serverDir = path.dirname(jarPath);

  // Odpowiednik 'docker run' - odpalenie Javy bezpośrednio na systemie
  const mcProcess = spawn('java', [
    `-Xms${ram}M`,
    `-Xmx${ram}M`,
    '-jar',
    jarPath,
    'nogui'
  ], { cwd: serverDir });

  activeProcesses.set(serverId, mcProcess);

  // Przekierowanie logów do Twojego UI przez WebSockety
  mcProcess.stdout.on('data', (data) => {
    const line = data.toString();
    // Tutaj wysyłasz 'line' przez socket.io do swojego komponentu Console
    console.log(`[MC LOG]: ${line}`);
  });

  mcProcess.on('close', (code) => {
    console.log(`Serwer ${serverId} wyłączony z kodem: ${code}`);
    activeProcesses.delete(serverId);
  });

  return mcProcess;
};

// Wysyłanie komend (Input z Twojego UI)
export const sendCommandLocal = (serverId: string, command: string) => {
  const process = activeProcesses.get(serverId);
  if (process) {
    process.stdin?.write(command + '\n');
  }
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { DashboardHome } from './components/DashboardHome';
import { ServerControl } from './components/ServerControl';
import { GlobalSettings } from './components/GlobalSettings';
import { Server } from './types';
import { INITIAL_SERVERS, generateMockStats } from './services/mockData';

const App: React.FC = () => {
  const [servers, setServers] = useState<Server[]>(INITIAL_SERVERS);
  const [activeServerId, setActiveServerId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [stats, setStats] = useState(generateMockStats());

  const activeServer = activeServerId ? servers.find(s => s.id === activeServerId) : null;

  // Simulate Live Updates for Stats
  useEffect(() => {
    const interval = setInterval(() => {
      setStats(prev => {
        const next = [...prev.slice(1)];
        next.push({
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          players: Math.max(0, prev[prev.length - 1].players + (Math.random() > 0.5 ? 1 : -1)),
          cpu: Math.min(100, Math.max(10, prev[prev.length - 1].cpu + (Math.random() * 10 - 5))),
          ram: Math.max(2, prev[prev.length - 1].ram + (Math.random() * 0.2 - 0.1))
        });
        return next;
      });
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  const handleUpdateServer = (updatedServer: Server) => {
    setServers(prev => prev.map(s => s.id === updatedServer.id ? updatedServer : s));
  };

  const handleAddServer = () => {
    alert("This feature is disabled in the demo. Imagine a beautiful modal appearing here!");
  };

  const handleSelectServer = (id: string | null) => {
    setActiveServerId(id);
    setIsSettingsOpen(false);
  };

  const handleOpenSettings = () => {
    setActiveServerId(null);
    setIsSettingsOpen(true);
  };

  let mainContent;
  if (isSettingsOpen) {
    mainContent = <GlobalSettings />;
  } else if (activeServer) {
    mainContent = <ServerControl server={activeServer} onUpdateServer={handleUpdateServer} />;
  } else {
    mainContent = <DashboardHome servers={servers} stats={stats} />;
  }

  return (
    <div className="flex h-screen w-full bg-[#0f172a] text-slate-200 font-sans overflow-hidden">
      <Sidebar 
        servers={servers} 
        activeServerId={activeServerId}
        isSettingsOpen={isSettingsOpen} 
        onSelectServer={handleSelectServer}
        onOpenSettings={handleOpenSettings}
        onAddServer={handleAddServer}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-[0.03] pointer-events-none" />
        {mainContent}
      </main>
    </div>
  );
};

export default App;

