import { spawn, ChildProcess } from 'child_process';
import path from 'path';

// Mapa do przechowywania aktywnych procesów w pamięci RAM backendu
const activeProcesses = new Map<string, ChildProcess>();

export const startServerLocal = (serverId: string, ram: number, jarPath: string, onLog: (log: string) => void, onClose: (code: number | null) => void) => {
  const serverDir = path.dirname(jarPath);

  // Odpowiednik 'docker run' - odpalenie Javy bezpośrednio na systemie
  const mcProcess = spawn('java', [
    `-Xms${ram}M`,
    `-Xmx${ram}M`,
    '-jar',
    jarPath,
    'nogui'
  ], { cwd: serverDir });

  activeProcesses.set(serverId, mcProcess);

  // Przekierowanie logów do Twojego UI przez WebSockety
  mcProcess.stdout.on('data', (data) => {
    const line = data.toString();
    onLog(line);
  });

  mcProcess.stderr.on('data', (data) => {
    const line = data.toString();
    onLog(line);
  });

  mcProcess.on('close', (code) => {
    console.log(`Serwer ${serverId} wyłączony z kodem: ${code}`);
    activeProcesses.delete(serverId);
    onClose(code);
  });

  return mcProcess;
};

// Wysyłanie komend (Input z Twojego UI)
export const sendCommandLocal = (serverId: string, command: string) => {
  const process = activeProcesses.get(serverId);
  if (process) {
    process.stdin?.write(command + '\n');
    return true;
  }
  return false;
};

