import express from 'express';
import http from 'http';
import { Server } from 'socket.io';
import { startServerLocal, sendCommandLocal } from './minecraft';

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173", // Allow frontend dev server
    methods: ["GET", "POST"]
  }
});

app.use(express.json());

// For now, let's keep server data in memory
const servers = [
    { id: '1', name: 'Vanilla', status: 'Offline', ram: 2048, jarPath: 'd:/minemanager/servers/vanilla/server.jar' },
    { id: '2', name: 'Forge', status: 'Offline', ram: 4096, jarPath: 'd:/minemanager/servers/forge/server.jar' },
];

app.get('/api/servers', (req, res) => {
  res.json(servers);
});

app.post('/api/servers/:id/start', (req, res) => {
    const serverId = req.params.id;
    const serverInfo = servers.find(s => s.id === serverId);

    if (!serverInfo) {
        return res.status(404).send('Server not found');
    }

    startServerLocal(
        serverId,
        serverInfo.ram,
        serverInfo.jarPath,
        (log) => {
            io.to(serverId).emit('log', log);
        },
        (code) => {
            io.to(serverId).emit('status', 'Offline');
            servers.find(s => s.id === serverId)!.status = 'Offline';
        }
    );

    serverInfo.status = 'Online';
    io.emit('status', { serverId, status: 'Online' });
    res.status(200).send('Server starting');
});

app.post('/api/servers/:id/command', (req, res) => {
    const serverId = req.params.id;
    const { command } = req.body;

    if (sendCommandLocal(serverId, command)) {
        res.status(200).send('Command sent');
    } else {
        res.status(404).send('Server not found or not running');
    }
});


io.on('connection', (socket) => {
  console.log('a user connected');

  socket.on('subscribe', (serverId) => {
    socket.join(serverId);
    console.log(`Socket ${socket.id} subscribed to server ${serverId}`);
  });

  socket.on('unsubscribe', (serverId) => {
    socket.leave(serverId);
    console.log(`Socket ${socket.id} unsubscribed from server ${serverId}`);
  });

  socket.on('disconnect', () => {
    console.log('user disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

